// Robust extraction across different OpenAI / LLM node output formats
let rawText = '';
const item = $input.item.json;

if (typeof item === 'string') {
  rawText = item;
} else if (item.text) {
  rawText = item.text;
} else if (item.response) {
  rawText = item.response;
} else if (item.output && Array.isArray(item.output) && item.output[0]?.content) {
  const contentObj = item.output[0].content;
  if (Array.isArray(contentObj) && contentObj[0]?.text) {
    rawText = contentObj[0].text;
  } else if (typeof contentObj === 'string') {
    rawText = contentObj;
  }
} else if (item.message && item.message.content) {
  rawText = typeof item.message.content === 'string' ? item.message.content : JSON.stringify(item.message.content);
} else {
  rawText = JSON.stringify(item);
}

// Clean markdown code fences and extraneous whitespace
rawText = rawText.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();

// Allowed values from the theme-routing v2 schema (Supabase 'emails' CHECK constraints)
const ALLOWED_THEMES = ['accounts', 'orders', 'finance', 'suppliers', 'promotions', 'nph_jobs', 'meetings_appointments', 'invoices', 'certificates'];
const ALLOWED_URGENCY = ['urgent', 'priority', 'normal'];
const ALLOWED_ROLES = ['director', 'senior_admin', 'progressor', 'accountant'];

// Authoritative theme -> routed_roles fallback mapping (used only if the model's
// routed_roles is missing/invalid — the model is expected to apply this itself)
const THEME_ROLE_MAP = {
  accounts: ['director'],
  orders: ['senior_admin'],
  finance: ['director'],
  suppliers: ['director', 'senior_admin'],
  promotions: ['senior_admin'],
  nph_jobs: ['senior_admin'],
  meetings_appointments: ['senior_admin', 'director'],
  invoices: ['director'],
  certificates: ['senior_admin', 'director'],
};

let parsedTheme = '';
let parsedUrgency = '';
let parsedRoles = [];
let parsedConfidence = 0.5;
let parsedSummary = '';

try {
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? jsonMatch[0] : rawText;
  const parsed = JSON.parse(jsonStr);
  if (parsed.theme) parsedTheme = String(parsed.theme).trim().toLowerCase();
  if (parsed.urgency) parsedUrgency = String(parsed.urgency).trim().toLowerCase();

  // routed_roles: defensively coerce a bare string into a one-element array
  if (Array.isArray(parsed.routed_roles)) {
    parsedRoles = parsed.routed_roles.map((r) => String(r).trim().toLowerCase());
  } else if (typeof parsed.routed_roles === 'string' && parsed.routed_roles.trim()) {
    parsedRoles = [parsed.routed_roles.trim().toLowerCase()];
  }

  if (parsed.confidence !== undefined) {
    const conf = parseFloat(parsed.confidence);
    if (!isNaN(conf)) parsedConfidence = Math.max(0, Math.min(1, conf));
  }
  if (parsed.summary) parsedSummary = String(parsed.summary).trim();
} catch (e) {
  // Regex fallback if JSON is malformed
  const themeMatch = rawText.match(/"theme"\s*:\s*"([^"]+)"/i);
  const urgencyMatch = rawText.match(/"urgency"\s*:\s*"([^"]+)"/i);
  const rolesMatch = rawText.match(/"routed_roles"\s*:\s*(\[[^\]]*\]|"[^"]+")/i);
  const confMatch = rawText.match(/"confidence"\s*:\s*([\d.]+)/i);
  const sumMatch = rawText.match(/"summary"\s*:\s*"([^"]+)"/i);
  if (themeMatch) parsedTheme = themeMatch[1].trim().toLowerCase();
  if (urgencyMatch) parsedUrgency = urgencyMatch[1].trim().toLowerCase();
  if (rolesMatch) {
    try {
      const rolesParsed = JSON.parse(rolesMatch[1]);
      parsedRoles = Array.isArray(rolesParsed)
        ? rolesParsed.map((r) => String(r).trim().toLowerCase())
        : [String(rolesParsed).trim().toLowerCase()];
    } catch (e2) {
      parsedRoles = [rolesMatch[1].replace(/"/g, '').trim().toLowerCase()];
    }
  }
  if (confMatch) parsedConfidence = Math.max(0, Math.min(1, parseFloat(confMatch[1])));
  if (sumMatch) parsedSummary = sumMatch[1].trim();
}

// Normalize and validate theme (fallback: 'accounts', low confidence — per prompt's own fallback rule)
const themeIsValid = ALLOWED_THEMES.includes(parsedTheme);
const finalTheme = themeIsValid ? parsedTheme : 'accounts';
if (!themeIsValid) parsedConfidence = Math.min(parsedConfidence, 0.3);

// Normalize and validate urgency (fallback: 'normal')
const finalUrgency = ALLOWED_URGENCY.includes(parsedUrgency) ? parsedUrgency : 'normal';

// Filter routed_roles to valid role strings only; fall back to the authoritative
// theme -> roles mapping if the model returned nothing usable
let finalRoles = parsedRoles.filter((r) => ALLOWED_ROLES.includes(r));
if (finalRoles.length === 0) {
  finalRoles = THEME_ROLE_MAP[finalTheme] || ['senior_admin'];
}

if (!parsedSummary) {
  parsedSummary = `Email from ${$('TEST EMAIL — NPH Job Update').item.json.from_name || 'sender'} regarding ${$('TEST EMAIL — NPH Job Update').item.json.subject || 'inquiry'}.`;
}

return {
  json: {
    theme: finalTheme,
    urgency: finalUrgency,
    routed_roles: finalRoles,
    confidence: parsedConfidence,
    summary: parsedSummary,
    raw_classification_text: rawText
  }
};

