// Email Dispatch with RFC 2822 In-Reply-To and References Threading Headers
const email = $('Supabase — Get Email').item.json;
const account = $('Supabase — Get Account1').item.json;
const sendFields = $('Extract Send Fields').item.json;

const originalSubject = email.subject || '';
const subject = originalSubject.toLowerCase().startsWith('re:') ? originalSubject : `Re: ${originalSubject}`;
const messageId = email.message_id || `<${Date.now()}@allsaintsbuilders.com>`;

const emailPayload = {
  from: account.email_address,
  to: email.from_address,
  subject: subject,
  body_text: sendFields.body_to_send,
  headers: {
    'In-Reply-To': messageId,
    'References': messageId,
    'X-Mailer': 'Foreman AI Email Agent'
  },
  dispatched_at: new Date().toISOString(),
  status: 'dispatched'
};

return { json: emailPayload };
